using System;
using EmberBastion;
class CandidateWaveIsolationChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){for(int f=0;f<Balance.Fields.Length;f++){
  var legacy=new Battle(1,f);var normal=Battle.CreateForRules(1,f,4);var reinforcement=Battle.CreateForRules(1,f,4);Check(reinforcement.EnableReinforcements(),"enable reinforcement");
  for(int w=0;w<normal.WaveCount;w++){var source=legacy.WaveGroups(w);var candidate=normal.WaveGroups(w);var other=reinforcement.WaveGroups(w);Check(!object.ReferenceEquals(source,candidate),"wave copy");Check(object.ReferenceEquals(source,other),"reinforcement uses legacy");Check(source.Length==candidate.Length,"group count");for(int i=0;i<source.Length;i++){var a=source[i];var b=candidate[i];Check(!object.ReferenceEquals(a,b),"group copy");bool convert=a.Extended&&a.Kind==0;Check(b.Kind==(convert?1:a.Kind)&&b.Count==(convert?(int)Math.Round(a.Count*.8):a.Count)&&b.Gap==(convert?a.Gap*2:a.Gap)&&a.Delay==b.Delay&&a.Gate==b.Gate&&a.Multiplier==b.Multiplier&&a.Extended==b.Extended,"candidate values");}}
  if(f<3){Group source=null,candidate=null;for(int w=0;w<normal.WaveCount&&candidate==null;w++)for(int i=0;i<normal.WaveGroups(w).Length;i++)if(normal.WaveGroups(w)[i].Extended&&normal.WaveGroups(w)[i].Kind!=4){source=legacy.WaveGroups(w)[i];candidate=normal.WaveGroups(w)[i];break;}Check(candidate!=null,"extended group present");Check(Math.Abs(normal.SpawnGap(candidate)-candidate.Gap/Math.Sqrt(2.5)/1.25)<1e-9,"candidate gap compression");Check(Math.Abs(legacy.SpawnGap(source)-source.Gap/2.5/1.25)<1e-9,"legacy gap unchanged");}
  if(f<3){normal.SetDifficulty(2);legacy.SetDifficulty(2);for(int w=0;w<normal.WaveCount;w++)for(int i=0;i<normal.WaveGroups(w).Length;i++){var g=normal.WaveGroups(w)[i];var oldGroup=legacy.WaveGroups(w)[i];if(!g.Extended||g.Kind==4)continue;double factor=f==1?1.5:1.7;Check(normal.SpawnCount(g)==(int)Math.Round(g.Count*factor),"extreme candidate count");Check(Math.Abs(normal.SpawnGap(g)-g.Gap/Math.Sqrt(factor))<1e-9,"extreme candidate gap");Check(legacy.SpawnCount(oldGroup)==(int)Math.Round(oldGroup.Count*1.7),"legacy extreme count");Check(Math.Abs(legacy.SpawnGap(oldGroup)-oldGroup.Gap/1.7)<1e-9,"legacy extreme gap");Check(reinforcement.SpawnCount(oldGroup)==(int)Math.Round(Math.Round(Math.Round(oldGroup.Count*1.4)*1.25)*1.15),"reinforcement extreme count");Check(Math.Abs(reinforcement.SpawnGap(oldGroup)-oldGroup.Gap/1.4/1.25/1.15)<1e-9,"reinforcement extreme gap");}}
  if(f==3){for(int mode=0;mode<3;mode++){var candidate=Battle.CreateForRules(3,3,4);candidate.SetDifficulty(mode);var baseBattle=new Battle(3,3);baseBattle.SetDifficulty(mode);for(int w=0;w<candidate.WaveCount;w++)for(int i=0;i<candidate.WaveGroups(w).Length;i++){var a=baseBattle.WaveGroups(w)[i];var c=candidate.WaveGroups(w)[i];bool boosted=mode==0&&w>=3&&a.Kind!=4;int expectedRaw=boosted?(int)Math.Round(a.Count*1.65):a.Count;int expected=mode==2||a.Kind==4?expectedRaw:(int)Math.Round(expectedRaw*1.25);Check(candidate.SpawnCount(c)==expected,"marsh count mode "+mode+" wave "+w);double gap=a.Gap/(boosted?1.65:1)/(mode==2||a.Kind==4?1:1.25);Check(Math.Abs(candidate.SpawnGap(c)-gap)<1e-9,"marsh gap");}}}
  var copy=normal.WaveGroups(0)[0];var original=legacy.WaveGroups(0)[0];int old=copy.Count;copy.Count++;Check(original.Count!=copy.Count,"independent mutation");copy.Count=old;
 }Console.WriteLine("PASS candidate wave isolation across four fields and modes");}
}
